import java.util.Scanner;

public class Main {
    public static int add(int a, int b) {
        return a + b;
    }

    public static int add(int a, int b, int c) {
        return a + b + c;
    }

    public static int add(int a, int b, int c, int d) {
        return a + b + c + d;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();
        System.out.println("两样之和 " + add(a, b) + " {unit}");
        System.out.println("三样之和 " + add(a, b, c) + " {unit}");
        System.out.println("四样之和 " + add(a, b, c, d) + " {unit}");
    }
}
